import ctypes
from pathlib import Path
import subprocess
import sys

# The ensure_admin function below was generated with the help of AI tools. This function checks if the app is being run as
# an administrator, and if not, it relaunches the app with elevated privileges. This is necessary for the TPM and system
# encryption checks to work properly. When running this app, the user will receive the User Account Control (UAC) prompt
# asking for permission to run the app as an administrator.

def ensure_admin():
    if ctypes.windll.shell32.IsUserAnAdmin():
        return

    script = str(Path(sys.argv[0]).resolve())
    params = subprocess.list2cmdline([script, *sys.argv[1:]])

    shell32 = ctypes.WinDLL("shell32", use_last_error=True)
    shell_execute = shell32.ShellExecuteW
    shell_execute.restype = ctypes.c_void_p

    result = shell_execute(
        None, "runas", sys.executable, params, str(Path.cwd()), 1
    )
    if result is None or result <= 32:
        raise OSError(f"Could not start elevated app (ShellExecuteW returned {result}).")

    raise SystemExit

ensure_admin()


import UserInterface

def main():
    UserInterface.root.mainloop()


if __name__ == "__main__":
    main()